import { atom } from 'jotai';

export type CartItem = { id: string; name: string; price: number };

export const itemsAtom = atom<CartItem[]>([]);

export const totalAtom = atom((get) =>
  get(itemsAtom).reduce((sum, item) => sum + item.price, 0)
);

// A write-only atom coordinates a complex update
export const addItemAtom = atom(null, (get, set, item: CartItem) => {
  set(itemsAtom, [...get(itemsAtom), item]);
});

import { useAtomValue, useSetAtom } from 'jotai';
import { itemsAtom, totalAtom, addItemAtom } from './atoms/cart';

export function Total() {
  const total = useAtomValue(totalAtom);   // re-renders only when total changes
  return <p>Total: ${total}</p>;
}

export function AddButton() {
  const add = useSetAtom(addItemAtom);     // never re-renders from state
  return <button onClick={() => add({ id: crypto.randomUUID(), name: 'Pen', price: 2 })}>Add</button>;
}

import { atom } from 'jotai';

export const productsAtom = atom(async () => {
  const res = await fetch('/api/products');
  if (!res.ok) throw new Error('Failed to load products');
  return (await res.json()) as { id: string; name: string }[];
});

